import React from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Home from './Components/Home';
import ConvertCase from './Components/ConvertCase';
import Navbar from './Components/Navbar';
import ContactUs from './Components/ContactUs'; // Ensure file name matches
import News from './Components/News';
import './App.css';

function App() {
  return (
    <Router>
      <div className="App">
        <Navbar Title="Cyber-Secs" /> {/* Navbar with a title prop */}

        {/* Define Routes */}
        <Routes>
          {/* Default Home Page */}
          <Route index element={<Home />} /> {/* Home as the default page */}
          <Route path="/home" element={<Home/>} /> {/* Optional: Alternate path for home */}

          {/* Convert-Case Page */}
          <Route
            path="/convertcase"
            element={<ConvertCase Heading="Enter Your Text Below" />}
          />

          {/* Contact Us Page */}
          <Route path="/Contactus" element={<ContactUs/>} />

          {/* News Page */}
          <Route
            path="/news"
            element={
              <News
                titlee="Latest News -Top Headlines"
                Description="Hello"
                Imageurl="https://static.vecteezy.com/system/resources/previews/003/691/525/non_2x/global-news-announcement-vector.jpg"
              />
            }
          />

          {/* Fallback for unknown routes */}
          <Route path="*" element={<Navigate to="/home" />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;