import React, { useState } from 'react';
import { jsPDF } from 'jspdf';
import './Home.css';

export default function Text(props) {
  const [inputText, setInputText] = useState('');
  const [openIndex, setOpenIndex] = useState(null);

  const toggleFAQ = (index) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  const faqData = [
    {
      question: 'How do I convert text to words?',
      answer: 'You can use a word counter tool or a text processing script to count words in a given text.',
    },
    {
      question: 'How can I convert an image to text?',
      answer: 'You can use Optical Character Recognition (OCR) software such as Tesseract or online tools.',
    },
    {
      question: 'How do I download text styles?',
      answer: 'Text styles can be downloaded from various font websites like Google Fonts or Font Squirrel.',
    },
    {
      question: 'How do I convert written words to text?',
      answer: 'Handwritten words can be converted to text using OCR technology or note-taking apps like Google Keep.',
    },
  ];

  const handleTextConversion = (type) => {
    const convertedText = type === 'uppercase' ? inputText.toUpperCase() : inputText.toLowerCase();
    setInputText(convertedText);
  };

  const handleClear = () => {
    setInputText('');
  };

  const handleDownload = (fileType) => {
    const fileName = 'khanobaid';
    if (fileType === 'text/plain') {
      const textFileAsBlob = new Blob([inputText], { type: fileType });
      const downloadLink = document.createElement('a');
      downloadLink.download = `${fileName}.txt`;
      downloadLink.href = window.URL.createObjectURL(textFileAsBlob);
      downloadLink.style.display = 'none';
      document.body.appendChild(downloadLink);
      downloadLink.click();
      document.body.removeChild(downloadLink);
      window.URL.revokeObjectURL(downloadLink.href);
    } else if (fileType === 'application/pdf') {
      const doc = new jsPDF();
      doc.text(inputText, 10, 10);
      doc.save(`${fileName}.pdf`);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(inputText)
      .then(() => alert('Text copied to clipboard!'))
      .catch(() => alert('Failed to copy text. Please try again.'));
  };

  const handleChange = (event) => {
    setInputText(event.target.value);
  };

  const wordCount = inputText.split(/\s+/).filter(word => word !== '').length;
  const readingTime = (wordCount * 0.008).toFixed(2);

  return (
    <>
      <div className="titleCase">
        <h1>Welcome To Case<span>Convert</span></h1>
        <img
          src="https://png.pngtree.com/thumb_back/fh260/background/20230701/pngtree-cartoon-illustration-of-children-reading-and-studying-image_4478702.jpg"
          alt="Background"
          className="header-image"
        />
        <div className="input-container">
          <h1>{props.Heading}</h1>
          <textarea
            className="input-textarea"
            placeholder="Type your message here..."
            value={inputText}
            onChange={handleChange}
            rows="4"
          />
          <button className="submit-button" onClick={() => handleTextConversion('uppercase')}>
            Convert to Uppercase
          </button>
          <button className="submit-button" onClick={() => handleTextConversion('lowercase')}>
            Convert to Lowercase
          </button>
          <button className="submit-button" onClick={handleClear}>
            Clear
          </button>
          <button className="submit-button" onClick={copyToClipboard}>
            Copy To Clipboard
          </button>
          <button className="submit-button" onClick={() => handleDownload('text/plain')}>
            Download as Text
          </button>
          <button className="submit-button" onClick={() => handleDownload('application/pdf')}>
            Download as PDF
          </button>
        </div>
      </div>
      <div className="Text">
        <h2>Your Summary Is Here</h2>
        <p>{wordCount} Words And {inputText.length} Characters</p>
        <p>{readingTime} Minutes To Read</p>
        <h2>Preview</h2>
        <p>{inputText}</p>
      </div>

      <div className="faq-container">
        {faqData.map((faq, index) => (
          <div className="faq-item" key={index}>
            <div
              className="faq-question"
              onClick={() => toggleFAQ(index)}
              role="button"
              tabIndex={0}
              aria-expanded={openIndex === index}
            >
              {faq.question}
              <span className="faq-toggle">
                {openIndex === index ? '▲' : '▼'}
              </span>
            </div>
            {openIndex === index && (
              <div className="faq-answer">{faq.answer}</div>
            )}
          </div>
        ))}
      </div>
      <footer>
        <h1>Text-<span>Tutor</span></h1>
        <p>&copy; 2023 Text-Tutor. All rights reserved.</p>
        <br />
        <p>Developed By - Khan Obaid</p>
      </footer>
    </>
  );
}