import React, { Component } from 'react';
import './News.css';
import './Home.css';
import { ClockLoader } from 'react-spinners';

export default class News extends Component {
  constructor() {
    super();
    this.state = {
      articles: [],
      loading: true,
      page: 1,
      totalResults: 0,
    };
  }

  async fetchNews(page) {
    try {
      this.setState({ loading: true });
      const pageSize = 9;
      const url = `https://newsapi.org/v2/top-headlines?country=us&category=business&apiKey=f1d8950bf05b427a8b0fa29d2548c7b2&page=${page}&pageSize=${pageSize}`;
      const response = await fetch(url);
      const data = await response.json();
      this.setState({
        articles: data.articles || [],
        loading: false,
        totalResults: data.totalResults || 0,
        page: page
      });
    } catch (error) {
      console.error("Error fetching news:", error);
      this.setState({ loading: false });
    }
  }

  componentDidMount() {
    this.fetchNews(this.state.page);
  }

  prev = async () => {
    if (this.state.page > 1) {
      this.fetchNews(this.state.page - 1);
    }
  }

  next = async () => {
    const { page, totalResults } = this.state;
    const pageSize = 9;
    if ((page + 1) <= Math.ceil(totalResults / pageSize)) {
      this.fetchNews(page + 1);
    }
  }

  render() {
    const { titlee } = this.props;
    const { articles, loading, page, totalResults } = this.state;
    const pageSize = 9;

    return (
      <>
        <div className='head'>
          <h1>{titlee}</h1>
          <img
            src='https://img.freepik.com/free-vector/news-reporter-photographer-with-globe_1308-37488.jpg'
            alt='news banner'
          />
        </div>

        <div className="news-container">
        {loading ? (
    <div className="spinner">
    <ClockLoader color="#000000" size={60} />
  </div>
) : articles.length === 0 ? (
  <p>No news articles found.</p>
) : (
  articles.map((article, index) => (
              <div className="news-component" key={index}>
                <img
                  src={article.urlToImage || 'https://via.placeholder.com/300x200?text=No+Image'}
                  alt="news"
                />
                <h2 className="news-title">{article.title || "Untitled"}</h2>
                <p className="news-description">{article.description || "No description available."}</p>
                <a  className="btn" href={article.url} target="_blank" rel="noopener noreferrer">Read More</a>
              </div>
            ))
          )}
        </div>

        <div className="pagination">
          <button disabled={page <= 1} onClick={this.prev}>← Previous</button>
          <span> Page {page} </span>
          <button
            disabled={(page + 1) > Math.ceil(totalResults / pageSize)}
            onClick={this.next}
          >
            Next →
          </button>
        </div>
        <div className="fo">
          <footer>
            <h1>Text-<span>Tutor</span></h1>
            <p>&copy; 2023 Text-Tutor. All rights reserved.</p>
            <br />
            <p>Developed By - Khan Obaid</p>
          </footer>
        </div>
      </>
    );
  }
}
